//go:build goexperiment.simd

// Package ontology registers the frozen MITRE ATT&CK (enterprise, ICS, mobile)
// crossed with D3FEND tables — generated by cmd/d3fendgen into attack_gen.go —
// into a gr4ph builder.
//
// The generated file carries the pinned source names and the table sizes; see
// the Source* and N* constants in attack_gen.go. Regenerate with `make gen`
// (network required once) and commit the result.
package ontology

import (
	"errors"
	"fmt"

	"github.com/fr0g-66723067/gr4ph"
)

// ErrBuilderNotEmpty is returned by Register when the builder already holds
// relations or nodes.
var ErrBuilderNotEmpty = errors.New("ontology: Register requires a fresh builder")

// Register adds every relation, node, hierarchy link and edge of the frozen
// tables to b, and returns the first error.
//
// The registration order is load-bearing: the builder assigns dense ids in
// registration order, so
//
//   - RelNames[i] / DefRelNames[i] must become plane i+1, matching the
//     generated Rel*/DefRel* constants;
//   - TTPIDs[i] must become technique index i, which makes TTPParents[i] a
//     valid direct index (parents sort before, and register before, their
//     children) and keeps every child block contiguous.
//
// Register requires a fresh, unbuilt builder: pre-registered relations or nodes
// would shift every dense id and silently misalign the tables, so an
// already-built or non-empty builder returns ErrBuilderNotEmpty.
//
// Callers own the builder; use NewBuilder, Register, Build for the frozen
// engine.
func Register(b *gr4ph.Builder) error {
	if b.Built() || b.TTPCount() != 0 || b.ArtifactCount() != 0 || b.CountermeasureCount() != 0 ||
		b.RelCount() != 0 || b.DefRelCount() != 0 {
		return ErrBuilderNotEmpty
	}
	for _, name := range RelNames {
		if _, err := b.AddRel(name); err != nil {
			return fmt.Errorf("relation %s: %w", name, err)
		}
	}
	for _, name := range DefRelNames {
		if _, err := b.AddDefRel(name); err != nil {
			return fmt.Errorf("defensive relation %s: %w", name, err)
		}
	}

	for i, id := range TTPIDs {
		parent := gr4ph.TTP(TTPParents[i])
		if _, err := b.AddTTP(id, TTPLabels[i], TTPDomains[i], parent, TTPAliases[i]...); err != nil {
			return fmt.Errorf("technique %s: %w", id, err)
		}
	}
	for i, name := range ArtifactNames {
		if _, err := b.AddArtifact(name, ArtifactLabels[i]); err != nil {
			return fmt.Errorf("artifact %s: %w", name, err)
		}
	}
	for i, id := range CountermeasureIDs {
		if _, err := b.AddCountermeasure(id, CountermeasureLabels[i]); err != nil {
			return fmt.Errorf("countermeasure %s: %w", id, err)
		}
	}

	for i := range OffEdgeTTP {
		if err := b.AddEdge(gr4ph.TTP(OffEdgeTTP[i]), gr4ph.Artifact(OffEdgeArt[i]), gr4ph.Rel(OffEdgeRel[i])); err != nil {
			return fmt.Errorf("offensive edge %d: %w", i, err)
		}
	}
	for i := range DefEdgeCM {
		if err := b.AddDefEdge(gr4ph.Countermeasure(DefEdgeCM[i]), gr4ph.Artifact(DefEdgeArt[i]), gr4ph.DefRel(DefEdgeRel[i])); err != nil {
			return fmt.Errorf("defensive edge %d: %w", i, err)
		}
	}
	for i := range DefendsCM {
		if err := b.AddDefendsEdge(gr4ph.Countermeasure(DefendsCM[i]), gr4ph.TTP(DefendsTTP[i])); err != nil {
			return fmt.Errorf("defends-against pair %d: %w", i, err)
		}
	}
	return nil
}
